sys_script_include.script:
var AESPortalChannelResolver = Class.create();
AESPortalChannelResolver.prototype = {

    PORTAL_CHANNEL_TABLE: 'x_733168_aes_portal_channel',

    initialize: function() {},

    getChannel: function(portalId) {
        if (!portalId)
            return null;

        var channel = new GlideRecord(this.PORTAL_CHANNEL_TABLE);
        channel.addQuery('portal', portalId);
        channel.addQuery('active', true);
        channel.query();

        if (!channel.next())
            return null;

        return channel.getUniqueValue();
    },

    type: 'AESPortalChannelResolver'
};
